const defaults=[['Musculação','◇',[1,3,5],3],['Corrida','↗',[2,4,5,0],4],['Leitura','▤',[],5],['Estudo','▧',[],5],['Codar','⌘',[],5],['Idiomas','◎',[],3],['Organização financeira','▣',[],1],['Escrever no diário','✎',[],3]].map((a,i)=>({id:String(i),name:a[0],icon:a[1],days:a[2],target:a[3],minutes:0}));
