function navigate(){page=location.hash.slice(1)||'inicio';if(!links.some(l=>l[0]===page))page='inicio';render()}window.addEventListener('hashchange',()=>{navigate();window.scrollTo(0,0)});
function heading(ey,title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}function card(title,body,extra=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${extra}</div>${body}</section>`}const empty=s=>`<div class="empty">${s}</div>`;
