function monthNav(){return `<div class="controls"><button class="tiny" aria-label="Mês anterior" onclick="changeMonth(-1)">‹</button><span style="font-size:13px;align-self:center">${month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</span><button class="tiny" aria-label="Próximo mês" onclick="changeMonth(1)">›</button></div>`}function changeMonth(n){month.setMonth(month.getMonth()+n);render()}
