function timerCard(){return `<section class="card timer center"><div class="cardhead"><h2>Tempo de foco</h2><span class="tag">Seu momento</span></div><p class="sub">Uma coisa de cada vez.</p><select id="timerhabit" aria-label="Atividade do cronômetro" onchange="timer.habit=this.value;save()" ${timer.start||timer.elapsed?'disabled':''}>${db.habits.map(h=>`<option value="${h.id}" ${timer.habit===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}<option value="social" ${timer.habit==='social'?'selected':''}>Redes sociais</option><option value="game" ${timer.habit==='game'?'selected':''}>Videogame</option></select><div class="timerdisplay" id="timerclock">${clock()}</div><div class="controls"><button class="primary" onclick="timerToggle()">${timer.start?'Pausar':'Iniciar'}</button><button onclick="finishTimer()">Encerrar</button></div><button class="tiny" style="margin-top:15px" onclick="sessionForm()">Registrar tempo manualmente</button></section>`}
