function render(){ $('#nav').innerHTML=links.map(l=>`<a href="#${l[0]}" class="${page===l[0]?'active':''}" title="${l[2]}"><span>${l[1]}</span>${l[2]}</a>`).join('');$('#breadcrumb').textContent='Meu espaço / '+links.find(l=>l[0]===page)[2];$('#date').textContent=now().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});let html='';if(page==='inicio'){let hs=todayHabits(),done=hs.filter(h=>completed(h.id,today())).length,pct=hs.length?Math.round(done/hs.length*100):0;html=heading('SEU DIA, NO SEU RITMO',`Bora dar mais um passo${window.habbitDisplayName?', '+esc(window.habbitDisplayName):''}.`,'Pequenas escolhas hoje. Uma vida com mais intenção.',`<div class="controls"><button onclick="newHabit()">Novo hábito</button><button onclick="weekForm()">▦ Preparar semana</button></div>`)+`<div class="layout"><div>${card('Seus hábitos de hoje',habitRows(),`<span class="tag">${done} de ${hs.length} concluídos</span>`)}${card('Um dia de cada vez',grid(),monthNav())}${card('Nesta semana',`<div class="weeklist">${plan(today()).map(h=>`<div><div class="weekrow"><b>${esc(h.name)}</b><span>${weekCount(h.id)} / ${h.target} dias</span></div><div class="progress"><i style="width:${Math.min(100,weekCount(h.id)/h.target*100)}%"></i></div></div>`).join('')}</div>`)}</div><div class="rightcol">${card('Seu progresso hoje',`<div class="ring" style="--pct:${pct}%"><span>${pct}%<small>do seu dia</small></span></div><p class="center sub">${done? 'Cada passo conta. Continue no seu ritmo.':'Seu próximo passo pode ser pequeno.'}</p>`)}${timerCard()}<section class="card banner"><div class="eyebrow">LEMBRETE GENTIL</div><h2 style="margin-top:14px">Constância vale<br>mais que perfeição.</h2><p>Seu único ritmo é o seu.</p><span class="bunny"><svg viewBox='0 0 48 52' aria-hidden='true' fill='none' xmlns='http://www.w3.org/2000/svg'><path d='M15 27C6 9 11 0 17 4c4 3 5 12 6 18C25 9 29 0 34 4c6 5-1 18-5 23 10 5 12 19 2 23H17C4 47 5 33 15 27Z' fill='currentColor'/><circle cx='18' cy='36' r='1.8' fill='white'/><circle cx='30' cy='36' r='1.8' fill='white'/><path d='m22 41 2 2 2-2' stroke='white' stroke-width='2' stroke-linecap='round'/></svg></span></section></div></div>`}if(page==='habitos')html=heading('CONSTÂNCIA','Meus hábitos','Planeje sua semana. Encontre seu ritmo.',`<div class="controls"><button onclick="weekForm()">Preparar semana</button><button class="primary" onclick="newHabit()">Novo hábito</button></div>`)+card('Seu mês',grid(),monthNav())+card('Hábitos e metas',plan(today()).map(h=>`<div class="habit"><div class="habiticon">${h.icon}</div><div class="habitbody"><b>${esc(h.name)}</b><small>${h.days.length?h.days.map(d=>['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][d]).join(', '):'Dias livres'} · ${h.target} dias/semana · ${h.minutes? h.minutes+' min/dia':'marcação simples'}</small></div><span>${weekCount(h.id)} / ${h.target}</span></div>`).join(''),`<button onclick="newHabit()">Novo hábito</button>`);if(page==='agenda')html=agenda();if(page==='tarefas')html=window.habbitTasksPage?window.habbitTasksPage():empty('Carregando tarefas…');if(page==='financeiro')html=finance();if(page==='treinos')html=workouts();if(page==='resumo')html=summary();if(page==='desafios')html=challenges();$('#content').innerHTML=html;window.habbitUpdateLayout?.();window.habbitTasksMounted?.()}
const field=(name,label,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`,select=(name,label,options,value='')=>`<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
