 if(!Number.isInteger(target)||target<1||target>7){toast(fixed?'Selecione pelo menos um dia da semana.':'Escolha uma meta de 1 a 7 dias.');return false;}
 if(!Number.isInteger(minutes)||minutes<0||minutes>1440){toast('Informe um tempo mínimo entre 0 e 1440 minutos.');return false;}
 const icons=['○','✦','▤','◎','◇','✎','♡','⌂'],h={id:uid(),name,icon:icons.includes(f.icon)?f.icon:'○',days,target,minutes,startsOn:today()},current=plan(today()).map(x=>({...x,days:[...x.days]}));
