function agenda(){let n=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(month.getDay()+6)%7;return heading('ESPAÇO PARA SEUS PLANOS','Minha agenda','Compromissos e contas, no mesmo calendário.',`<button class="primary" onclick="eventForm()">Novo compromisso</button>`)+card('Calendário mensal',`<div class="calendar">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>`<div class="center muted">${d}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:n},(_,i)=>{let date=iso(new Date(month.getFullYear(),month.getMonth(),i+1));return `<div class="calday ${date===today()?'today':''}" role="button" tabindex="0" onclick="dayAgenda('${date}')" onkeydown="if(event.key==='Enter')dayAgenda('${date}')"><b>${i+1}</b>${db.events.filter(e=>e.date===date).map(e=>`<div class="event">${esc(e.time)} ${esc(e.title)}</div>`).join('')}${db.money.filter(m=>m.date===date&&m.type==='out').map(m=>`<div class="event bill">${m.paid?'✓ ':''}${esc(m.title)}</div>`).join('')}</div>`}).join('')}</div>`,monthNav())}
function eventForm(date=today(),id){let e=db.events.find(e=>e.id===id)||{};modalForm(id?'Editar compromisso':'Novo compromisso',field('title','Título','text',e.title||'','required')+field('date','Data','date',e.date||date,'required')+field('time','Horário (opcional)','time',e.time||'')+field('place','Local','text',e.place||'')+field('notes','Observações','text',e.notes||'')+(id?`<button type="button" onclick="deleteItem('events','${id}');modal.close()">Excluir compromisso</button>`:''),f=>{if(id)Object.assign(e,f);else db.events.push({id:uid(),...f})})}
