function finance(){let rows=db.money.filter(inMonth).sort((a,b)=>a.date.localeCompare(b.date)),actual=+db.initial+db.money.filter(m=>m.paid&&(m.actualDate||m.date)<=today()).reduce((a,m)=>a+(m.type==='in'?m.value:-m.value),0),pay=rows.filter(m=>!m.paid&&m.type==='out').reduce((a,m)=>a+m.value,0),receive=rows.filter(m=>!m.paid&&m.type==='in').reduce((a,m)=>a+m.value,0);return heading('CLAREZA PARA DECIDIR','Meu financeiro','O que entrou, o que saiu e o que está por vir.',`<button class="primary" onclick="moneyForm()">Novo lançamento</button>`)+`<div class="stats">${[['Saldo atual',actual],['A pagar no mês',pay],['A receber no mês',receive],['Saldo previsto',actual+receive-pay]].map(([t,v])=>`<div class="card stat"><span class="muted">${t}</span><strong>${money(v)}</strong></div>`).join('')}</div>`+card('Lançamentos',`<div class="gridwrap"><table class="table"><thead><tr><th>Descrição</th><th>Data</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.title)}<div class="sub">${esc(m.category)}</div></td><td>${parse(m.date).toLocaleDateString('pt-BR')}</td><td style="color:${m.type==='in'?'#548b6a':'#9d715e'}">${m.type==='in'?'+':'−'} ${money(m.value)}</td><td>${m.paid?m.type==='in'?'Recebido':'Pago':m.date<today()?'Vencido':m.type==='in'?'A receber':'A pagar'}</td><td><button class="tiny" onclick="pay('${m.id}')">${m.paid?'Reabrir':'Confirmar'}</button> <button class="tiny" aria-label="Excluir lançamento" onclick="deleteItem('money','${m.id}')">✕</button></td></tr>`).join('')}</tbody></table>${!rows.length?empty('Adicione sua primeira entrada, saída ou conta prevista.') :''}</div>`,monthNav())+`<button onclick="initialForm()">Ajustar saldo inicial</button><p class="sub">Saldo previsto considera o saldo atual e os pendentes do mês selecionado.</p>`}
function initialForm(){modalForm('Saldo inicial',field('value','Valor anterior aos lançamentos','number',db.initial,'step="0.01" required'),f=>db.initial=+f.value)}
function moneyForm(){modalForm('Novo lançamento',field('title','Descrição','text','','required')+select('type','Tipo',[['out','Saída / conta a pagar'],['in','Entrada / valor a receber']])+field('value','Valor (R$)','number','','min="0.01" step="0.01" required')+field('date','Data / vencimento','date',today(),'required')+field('category','Categoria','text','')+select('paid','Situação',[['no','Pendente'],['yes','Já pago / recebido']])+select('repeat','Repetição',[['0','Sem repetição'],['3','Mensal por 3 meses'],['6','Mensal por 6 meses'],['12','Mensal por 12 meses']]),f=>{let count=+f.repeat||1;for(let i=0;i<count;i++){let d=parse(f.date),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+i);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));db.money.push({id:uid(),title:f.title,type:f.type,value:+f.value,date:iso(d),category:f.category,paid:i===0&&f.paid==='yes'})}})}function pay(id){let m=db.money.find(m=>m.id===id);if(m.paid){m.paid=false;delete m.actualDate;save();render();return;}modalForm(m.type==='in'?'Confirmar recebimento':'Confirmar pagamento',`<p>${esc(m.title)} · ${money(m.value)}</p>`+field('date','Data efetiva','date',today(),`required max="${today()}"`),f=>{m.paid=true;m.actualDate=f.date})}
function deleteItem(key,id){if(!confirm('Excluir este registro?'))return;db[key]=db[key].filter(x=>x.id!==id);save();render()}
function workouts(){return heading('MOVIMENTO É PROGRESSO','Meus treinos','Suas fichas e cada sessão, no seu ritmo.',`<div class="controls"><button onclick="runForm()">Registrar corrida</button><button class="primary" onclick="workoutForm()">Novo treino</button></div>`)+`<div class="twocol"><div>${card('Treinos salvos',db.workouts.map(w=>`<div class="habit"><div class="habitbody"><b>${esc(w.name)}</b><small>${w.exercises.length} exercícios</small></div><button class="tiny" onclick="workoutForm('${w.id}')">Editar</button><button class="tiny" onclick="logWorkout('${w.id}')">Registrar</button><button class="tiny" onclick="deleteItem('workouts','${w.id}')">✕</button></div>`).join('')||empty('Cadastre seu primeiro treino. Ele ficará salvo para reutilizar.'))}</div><div>${card('Histórico de sessões',db.sessions.filter(s=>s.habit==='0'||s.habit==='1').slice().reverse().map(s=>`<div class="habit"><div class="habitbody"><b>${esc(s.name||habit(s.habit)?.name)}</b><small>${parse(s.date).toLocaleDateString('pt-BR')} · ${dur(s.seconds)}${s.distance?' · '+s.distance+' km · '+pace(s.seconds,s.distance)+'/km':''}</small>${s.exercises?`<p class="sub">${s.exercises.map(e=>esc(e)).join('<br>')}</p>`:''}<p class="sub">${esc(s.notes||'')}</p></div></div>`).join('')||empty('Seus treinos concluídos aparecerão aqui.'))}</div></div>`}
function workoutForm(id){let w=db.workouts.find(w=>w.id===id);modalForm('Treino de musculação',field('name','Nome do treino','text',w?.name||'','required')+`<label class="field">Exercícios — um por linha<textarea name="exercises" required placeholder="Supino reto | 3 séries | 10 repetições | 20 kg">${esc(w?.exercises.join('\n')||'')}</textarea></label><p class="sub">Você pode indicar cargas e repetições diferentes por série na mesma linha.</p>`,f=>{let v={name:f.name,exercises:f.exercises.split('\n').filter(s=>s.trim())};if(w)Object.assign(w,v);else db.workouts.push({id:uid(),...v})})}
function logWorkout(id){let w=db.workouts.find(w=>w.id===id),last=db.sessions.filter(s=>s.workout===id).at(-1);modalForm('Registrar · '+w.name,field('date','Data','date',today(),`required max="${today()}"`)+field('minutes','Duração (minutos)','number','','min="1" required')+`<label class="field">Exercícios e cargas desta sessão<textarea name="exercises" required>${esc((last?.exercises||w.exercises).join('\n'))}</textarea></label>`+field('notes','Observações'),f=>addSession('0',f.date,+f.minutes*60,{name:w.name,workout:id,exercises:f.exercises.split('\n'),notes:f.notes}))}
function pace(s,km){let p=Math.round(s/km);return Math.floor(p/60)+':'+String(p%60).padStart(2,'0')}
function runForm(){modalForm('Registrar corrida',field('date','Data','date',today(),`required max="${today()}"`)+field('distance','Distância (km)','number','','min="0.01" step="0.01" required')+field('minutes','Tempo total (minutos)','number','','min="0.1" step="0.1" required')+field('notes','Observações')+'<p class="sub">O pace será calculado automaticamente em min/km.</p>',f=>addSession('1',f.date,+f.minutes*60,{distance:+f.distance,notes:f.notes}))}
function challenges(){let week=wid(),end=parse(week);end.setDate(end.getDate()+6);let ss=db.sessions.filter(s=>s.date>=week&&s.date<=iso(end)),read=ss.filter(s=>s.habit==='2').reduce((a,s)=>a+s.seconds,0),social=ss.filter(s=>s.habit==='social').reduce((a,s)=>a+s.seconds,0),target=social*(1+db.goals.ratio/100),monthRead=db.sessions.filter(s=>inMonth(s)&&s.habit==='2').reduce((a,s)=>a+s.seconds/60,0);return heading('UMA DISPUTA COM VOCÊ','Metas e desafios','Sua semana começa na segunda. Cada semana é um novo começo.',`<button onclick="goalForm()">Configurar metas</button>`)+`<div class="twocol">${card('Leitura × redes sociais',`<span class="tag">Desafio semanal · +${db.goals.ratio}%</span><p>Leitura: <b>${dur(read)}</b> · Redes sociais: <b>${dur(social)}</b></p><div class="progress"><i style="width:${target?Math.min(100,read/target*100):0}%"></i></div><h3>${!social?'Registre seu tempo em redes sociais para comparar.':read>=target?'Meta atingida até agora!':`Faltam ${dur(target-read)} de leitura.`}</h3><p class="sub">Informe manualmente o tempo de uso do celular. A meta acompanha seus novos registros.</p><button onclick="sessionForm()">Registrar tempo</button>`)}${card('Leitura no mês',`<h1>${(monthRead/60).toFixed(1)} <span class="muted">/ ${(db.goals.reading/60).toFixed(1)} horas</span></h1><div class="progress"><i style="width:${Math.min(100,monthRead/db.goals.reading*100)}%"></i></div><p>Uma meta independente do tempo em redes sociais.</p>`,monthNav())}</div>`+card('Metas de frequência',plan(today()).map(h=>`<div class="habit"><div class="habitbody"><b>${esc(h.name)}</b><small>${weekCount(h.id)} de ${h.target} dias concluídos nesta semana</small></div><span class="tag">${weekCount(h.id)>=h.target?'Atingida':'Em andamento'}</span></div>`).join(''))}
function ratioAt(date){const keys=Object.keys(db.challengePlans||{}).filter(k=>k<=startWeek(parse(date))).sort();return keys.length?db.challengePlans[keys.at(-1)]:20}
function goalForm(){modalForm('Configurar metas',field('reading','Leitura mínima mensal (horas)','number',db.goals.reading/60,'min="0.1" step="0.1" required')+field('ratio','Leitura acima de redes sociais (%)','number',db.goals.ratio,'min="0" required'),f=>{db.goals={reading:+f.reading*60,ratio:+f.ratio};db.challengePlans??={};db.challengePlans[wid()]=+f.ratio})}
function summary(){let ss=db.sessions.filter(inMonth),groups={};ss.forEach(s=>{let name=['0','1'].includes(s.habit)?'Treinos':habit(s.habit)?.name||({social:'Redes sociais',game:'Videogame'}[s.habit]||'Outros');groups[name]=(groups[name]||0)+s.seconds});let total=ss.reduce((n,s)=>n+s.seconds,0),max=Math.max(1,...Object.values(groups));let days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),planned=0,done=0;for(let d=1;d<=days;d++){let date=iso(new Date(month.getFullYear(),month.getMonth(),d));if(date>today()||date<(db.created||today()))continue;plan(date).forEach(h=>{if(h.days.includes(parse(date).getDay())){planned++;if(completed(h.id,date))done++}})}return heading('OLHE O CAMINHO PERCORRIDO','Seu mês em perspectiva','Tempo dedicado, hábitos construídos e pequenos avanços.',`<button onclick="sessionForm()">Registrar tempo</button>`)+`<div class="stats">${[['Tempo registrado',dur(total)],['Sessões',ss.length],['Dias planejados cumpridos',`${done} / ${planned}`],['Atividades',Object.keys(groups).length]].map(([t,v])=>`<div class="card stat"><span class="muted">${t}</span><strong>${v}</strong></div>`).join('')}</div>`+card('Onde seu tempo floresceu',Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([name,s])=>`<div class="barrow"><b>${esc(name)}</b><div class="bar"><i style="width:${s/max*100}%"></i></div><span>${dur(s)} · ${Math.round(s/total*100)}%</span></div>`).join('')||empty('Inicie o cronômetro ou registre uma sessão para ver seu gráfico.'),monthNav())+card('Histórico de tempo',`<div class="gridwrap"><table class="table"><thead><tr><th>Atividade</th><th>Data</th><th>Duração</th><th></th></tr></thead><tbody>${ss.slice().reverse().map(s=>`<tr><td>${esc(habit(s.habit)?.name||({social:'Redes sociais',game:'Videogame'}[s.habit]||'Atividade'))}</td><td>${parse(s.date).toLocaleDateString('pt-BR')}</td><td>${dur(s.seconds)}</td><td><button class="tiny" onclick="deleteSession('${s.id}')">Excluir</button></td></tr>`).join('')}</tbody></table></div>`)+card('Desafios semanais encerrados',closedWeeks())}
function closedWeeks(){let out=[];for(let d=1;d<=31;d++){let end=new Date(month.getFullYear(),month.getMonth(),d);if(end.getMonth()!==month.getMonth())break;if(end.getDay()!==0||iso(end)>=today()||iso(end)<(db.created||today()))continue;let st=startWeek(end),ss=db.sessions.filter(s=>s.date>=st&&s.date<=iso(end)),r=ss.filter(s=>s.habit==='2').reduce((a,s)=>a+s.seconds,0),soc=ss.filter(s=>s.habit==='social').reduce((a,s)=>a+s.seconds,0);out.push(`<div class="habit"><div class="habitbody"><b>${parse(st).toLocaleDateString('pt-BR')} a ${end.toLocaleDateString('pt-BR')}</b><small>Leitura ${dur(r)} · Redes sociais ${dur(soc)}</small></div><span class="tag">${!soc?'Sem comparação':r>=soc*(1+ratioAt(st)/100)?'Meta atingida':'Não atingida'}</span></div>`)}return out.join('')||empty('As semanas encerradas aparecerão aqui.')}
function deleteSession(id){if(!confirm('Excluir esta sessão? Revise a conclusão do hábito após excluir.'))return;let removed=db.sessions.find(s=>s.id===id);db.sessions=db.sessions.filter(s=>s.id!==id);let h=habit(removed.habit,removed.date);if(h)db.checks[removed.date+'|'+removed.habit]=h.minutes?minutes(h.id,removed.date)>=h.minutes:db.sessions.some(s=>s.habit===h.id&&s.date===removed.date);save();render()}
function backup(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='habbit-backup-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}async function restore(e){try{let v=JSON.parse(await e.target.files[0].text());if(!Array.isArray(v.habits)||!Array.isArray(v.sessions)||!v.plans||!Array.isArray(v.money)||!Array.isArray(v.events)||!Array.isArray(v.workouts)||!v.checks||!v.goals)throw Error();if(!confirm('Substituir os dados atuais pelo backup?'))return;db=v;timer=v.timer||{habit:'2',elapsed:0,start:null};save();render();toast('Backup restaurado.')}catch{toast('Arquivo de backup inválido.')}}
navigate();
// Structured exercise rows keep saved templates independent from session snapshots.
function exerciseRow(e={}){if(typeof e==='string'){let a=e.split('|').map(x=>x.trim());e={name:a[0]||'',sets:a[1]||'',reps:a[2]||'',load:a[3]||''}}return `<div class="exerciseedit">${field('exname','Exercício','text',e.name||'','required')}<div class="exercisevalues">${field('exsets','Séries','text',e.sets||'','required placeholder="3"')}${field('exreps','Repetições','text',e.reps||'','required placeholder="10 / 10 / 8"')}${field('exload','Carga (kg)','text',e.load||'','placeholder="20 / 20 / 22"')}</div><button type="button" class="tiny" onclick="this.closest('.exerciseedit').remove()">Remover exercício</button></div>`}
function addExercise(){document.querySelector('#exercises').insertAdjacentHTML('beforeend',exerciseRow())}
function collectExercises(){return [...document.querySelectorAll('.exerciseedit')].map(row=>['exname','exsets','exreps','exload'].map(k=>row.querySelector(`[name="${k}"]`).value.trim()).join(' | '))}
workoutForm=function(id){let w=db.workouts.find(w=>w.id===id);modalForm(w?'Editar treino':'Novo treino',field('name','Nome do treino','text',w?.name||'','required')+`<div id="exercises">${(w?.exercises||[{}]).map(exerciseRow).join('')}</div><button type="button" onclick="addExercise()">Adicionar exercício</button><p class="sub">Para variar por série, use barras: 10 / 10 / 8 repetições.</p>`,f=>{let exercises=collectExercises();if(!exercises.length){toast('Adicione ao menos um exercício.');return false}let v={name:f.name,exercises};if(w)Object.assign(w,v);else db.workouts.push({id:uid(),...v})})};
